WITH matched_keys AS (SELECT page, event_type FROM web_events EXCEPT DISTINCT SELECT page, event_type FROM web_events WHERE event_type != 'purchase'), kept_rows AS (SELECT s.* FROM web_events s INNER JOIN matched_keys k ON s.page = k.page AND s.event_type = k.event_type) SELECT s.id, s.session_id, s.event_type, s.page, s.event_time, s.duration_sec, (SELECT SUM(x.duration_sec) FROM web_events x WHERE x.session_id = s.session_id) AS sum_web_event_duration_sec FROM kept_rows s
